preConditionHook:
// DOUBLE SWING LEVEL BREAK, RETEST, CONTINUE (Brian's notes ON-4, #4, p.3).
// The note's case is the short: support from the two most recent
// swingStrength-bar swing lows at a similar price (within levelTolAtr ATRs of
// each other), level S = the LOWER of the two, not yet closed below. A close
// below S is the break bar. The very first later bar whose high comes back
// above S is the setup bar. The first RED bar closing below S, at or after the
// setup bar (the setup bar may itself be the signal) and no later than the
// maxBarsAfterBreak-th bar after the break, is the signal: short at its close
// (next open). A close back above S by any bar after the setup bar, before
// the signal, invalidates. The long is the mirror: resistance R = the higher
// of the two most recent swing highs, a close above, a low back below R, and
// a GREEN close above R. "high or close that re-enters" collapses to the high
// (long: the low), since a close back across implies it.
//
// Each break bar bb = 1 .. maxBarsAfterBreak is tried in turn. The two pivots
// are read AS OF the break bar -- candidates at bars-ago bb + swingStrength ..
// bb + pivotLookback - 1, SwingHighBar's window shifted by bb -- so pivots
// confirmed after the break cannot move the level. "Not yet broken" means no
// close beyond the level since the NEWER pivot, so bb is the first break.
// "Similar" reads the CURRENT ATR, as the spec writes it.
//
//
// Pivot scan hand-rolled as in SwingPivotTarget (the register lists SwingHigh's
// Occurrence 3+ as unmeasured, and a lagged SwingHigh read is unregistered).
// MEASURED (EL_Swing_Probe.txt): the pivot bar is AT OR ABOVE the swingStrength
// OLDER bars and STRICTLY ABOVE the swingStrength NEWER bars -- bars-ago
// indexing, so the newer bars are the smaller kk; lag exactly swingStrength;
// the low side's tie sense mirrors the measured high side. No Break -- not a
// registered word.
//
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, ported from
// AtrProfitTarget (the reference, with the measurements). Seeded with a full
// sum on the first calculated bar or when the length changes, and updated
// thereafter as TWO statements -- EL evaluates S[1] + in - out left to right,
// and folding it to S += in - out rounds differently. The local counter is
// atrLen, not the input.
if (atrLen != (int)atrLength) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLength; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLen = (int)atrLength;
} else {
    const int out = (int)atrLength;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atrVal = atrSum / (int)atrLength;
fireL = false;
fireS = false;
for (int bb = 1; bb <= (int)maxBarsAfterBreak; ++bb) {
    nH = 0;
    nL = 0;
    hPx1 = 0.0;
    hPx2 = 0.0;
    hBar1 = 0;
    lPx1 = 0.0;
    lPx2 = 0.0;
    lBar1 = 0;
    for (int jj = bb + (int)swingStrength; jj <= bb + (int)pivotLookback - 1; ++jj) {
        okH = true;
        okL = true;
        for (int kk = jj - (int)swingStrength; kk <= jj - 1; ++kk) {
            if (el_le(high[jj], high[kk])) okH = false;
            if (el_ge(low[jj], low[kk])) okL = false;
        }
        for (int kk = jj + 1; kk <= jj + (int)swingStrength; ++kk) {
            if (el_lt(high[jj], high[kk])) okH = false;
            if (el_gt(low[jj], low[kk])) okL = false;
        }
        if (okH && nH < 2) {
            nH = nH + 1;
            if (nH == 1) {
                hPx1 = high[jj];
                hBar1 = jj;
            }
            if (nH == 2) hPx2 = high[jj];
        }
        if (okL && nL < 2) {
            nL = nL + 1;
            if (nL == 1) {
                lPx1 = low[jj];
                lBar1 = jj;
            }
            if (nL == 2) lPx2 = low[jj];
        }
    }
    // long: resistance from the two swing highs
    if (nH == 2 && !fireL) {
        if (el_le(std::fabs(hPx1 - hPx2), levelTolAtr * atrVal)) {
            lvl = hPx1;
            if (el_gt(hPx2, lvl)) lvl = hPx2;
            okBrk = el_gt(close[bb], lvl);
            for (int kk = bb + 1; kk <= hBar1 - 1; ++kk) {
                if (el_gt(close[kk], lvl)) okBrk = false;
            }
            if (okBrk) {
                sBar = -1;
                for (int kk = bb - 1; kk >= 0; --kk) {
                    if (sBar == -1 && el_lt(low[kk], lvl)) sBar = kk;
                }
                if (sBar != -1) {
                    okSet = true;
                    for (int kk = 1; kk <= sBar - 1; ++kk) {
                        if (el_lt(close[kk], lvl)) okSet = false;
                    }
                    for (int kk = 1; kk <= sBar; ++kk) {
                        if (el_gt(close[kk], open[kk]) && el_gt(close[kk], lvl)) okSet = false;
                    }
                    if (okSet && el_gt(close[0], open[0]) && el_gt(close[0], lvl)) fireL = true;
                }
            }
        }
    }
    // short: support from the two swing lows -- the note's own case
    if (nL == 2 && !fireS) {
        if (el_le(std::fabs(lPx1 - lPx2), levelTolAtr * atrVal)) {
            lvl = lPx1;
            if (el_lt(lPx2, lvl)) lvl = lPx2;
            okBrk = el_lt(close[bb], lvl);
            for (int kk = bb + 1; kk <= lBar1 - 1; ++kk) {
                if (el_lt(close[kk], lvl)) okBrk = false;
            }
            if (okBrk) {
                sBar = -1;
                for (int kk = bb - 1; kk >= 0; --kk) {
                    if (sBar == -1 && el_gt(high[kk], lvl)) sBar = kk;
                }
                if (sBar != -1) {
                    okSet = true;
                    for (int kk = 1; kk <= sBar - 1; ++kk) {
                        if (el_gt(close[kk], lvl)) okSet = false;
                    }
                    for (int kk = 1; kk <= sBar; ++kk) {
                        if (el_lt(close[kk], open[kk]) && el_lt(close[kk], lvl)) okSet = false;
                    }
                    if (okSet && el_lt(close[0], open[0]) && el_lt(close[0], lvl)) fireS = true;
                }
            }
        }
    }
}
